83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        if (!normalizeNewOwner(owner)) {
114	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
115	        }
116	        if (dailyLimitReached(owner.getRegistrationDate())) {
117	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
118	        }
119	        if (cityIsAtCapacity(owner.getCity())) {
120	            return new ResponseEntity<>(HttpStatus.CONFLICT);
121	        }
122	        owner.setHouseholdId(owner.computeHouseholdId());
123	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
124	        Optional<Owner> householdMember = findHouseholdMember(owner);
125	        if (householdMember.isPresent() && !sharesHousehold) {
126	            return new ResponseEntity<>(HttpStatus.CONFLICT);
127	        }
128	        boolean declaredHouseholdMember = householdMember.isPresent();
129	        assignDerivedAttributes(owner, declaredHouseholdMember);
130	        this.clinicService.saveOwner(owner);
131	        auditOwnerCreated(owner);
132	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
133	        headers.setLocation(UriComponentsBuilder.newInstance()
134	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
135	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
141	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
142	        if (currentOwner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        currentOwner.setAddress(ownerFieldsDto.getAddress());
146	        currentOwner.setCity(ownerFieldsDto.getCity());
147	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
148	        currentOwner.setLastName(ownerFieldsDto.getLastName());
149	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
150	        String email = ownerFieldsDto.getEmail();
151	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
152	        this.clinicService.saveOwner(currentOwner);
153	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Transactional
158	    @Override
159	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
160	        Owner owner = this.clinicService.findOwnerById(ownerId);
161	        if (owner == null) {
162	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
163	        }
164	        owner.setDeleted(true);
165	        this.clinicService.saveOwner(owner);
166	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
167	    }
